-
-	async recover(
-		entries: readonly SessionEntryLike[],
-		reason: "startup" | "reload" | "new" | "resume" | "fork" | "tree",
-		scope: MissionScope,
-		currentDigests?: { policyDigest: string; contextDigest: string },
