-	// Leg width: 2 blocks | Gap: 4 blocks
-	const lineLeg = `     ${piBlue(BLOCK.repeat(2))}    ${piBlue(BLOCK.repeat(2))}`;
-
-	// --- ASSEMBLY ---
-	return ["", lineEyes, lineBar, lineLeg, lineLeg, lineLeg, lineLeg, ""];
