-		encoding: "utf8",
-		input: opts?.input,
-		maxBuffer: 64 * 1024 * 1024,
-		timeout: 60_000,
-		env: { ...process.env, GIT_OPTIONAL_LOCKS: "0", GIT_PAGER: "cat", PAGER: "cat" },
